AuthorizationDecision.INTENT_MISMATCH,"Intent mismatch.");var id=AuthorizationArtifact.H(string.Join("|","request",a.AuthorizationId,p.ProposalId,d.Digest,i?.MutationIntentId??"legacy",p.Operation,p.TargetId??""));return new(AuthorizationDecision.AUTHORIZED,true,new(id,id,p.ProposalId,p.StateBinding,a,p.RuleId,p.FindingReference,p.EvidenceReferences,p.Operation,p.TargetId,i),i is null?"Explicit intent and exact state binding verified; request carries no mutation authority.":"Exact mutation intent authorized.");}}


